package com.smartcoms.hms.controller;
import com.smartcoms.hms.repository.*; import org.springframework.stereotype.*; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.*;
@Controller public class DashboardController { private final PatientRepository patients; private final BedRepository beds; private final AppointmentRepository appointments; public DashboardController(PatientRepository p,BedRepository b,AppointmentRepository a){patients=p;beds=b;appointments=a;} @GetMapping("/dashboard") String dashboard(Model m){m.addAttribute("patientCount",patients.count());m.addAttribute("appointmentCount",appointments.countByDate(LocalDate.now()));m.addAttribute("availableBeds",beds.countByStatus("Available"));m.addAttribute("occupiedBeds",beds.countByStatus("Occupied"));m.addAttribute("todayAppointments",appointments.findTop8ByDateOrderByTimeAsc(LocalDate.now()));return "dashboard";} @GetMapping("/patients") String patientList(@RequestParam(required=false) String q,Model m){m.addAttribute("patients",q==null?patients.findAll():patients.findByFullNameContainingIgnoreCaseOrPatientCodeContainingIgnoreCase(q,q));m.addAttribute("q",q);return "patients/list";} @GetMapping("/patients/new") String newPatient(Model m){m.addAttribute("patient",new com.smartcoms.hms.entity.Patient());return "patients/form";} @PostMapping("/patients") String savePatient(@jakarta.validation.Valid @ModelAttribute com.smartcoms.hms.entity.Patient p,org.springframework.validation.BindingResult errors){if(errors.hasErrors())return "patients/form";p.setPatientCode("CA-"+(1001+patients.count()));patients.save(p);return "redirect:/patients?created";} @GetMapping("/beds") String bedList(Model m){m.addAttribute("beds",beds.findAll());return "beds";} @GetMapping("/appointments/manage") String manageAppointments(Model m){m.addAttribute("appointments",appointments.findAll());return "appointments";} }
